@app.route("/admin/customers", methods=["GET"])
@admin_required
def admin_customers():
    search_query = request.args.get("q", "").strip()[:120]
    customers = get_customer_directory_data(search_query)
    return render_template_string(
        CUSTOMERS_TEMPLATE,
        customers=customers,
        customer_count=len(customers),
        open_customer_count=sum(1 for item in customers if item.get("open_enquiry_count", 0) > 0),
        enquiry_count=sum(int(item.get("enquiry_count", 0)) for item in customers),
        search_query=search_query,
    )


