@app.route("/admin/inbox", methods=["GET"])
@admin_required
def admin_inbox():
    search_query = request.args.get("q", "").strip()[:120]
    customers = get_admin_inbox_customers(search_query)
    return render_template_string(
        INBOX_TEMPLATE,
        customers=customers,
        customer_count=len(customers),
        paused_count=sum(1 for item in customers if item.get("ai_paused")),
        search_query=search_query,
    )


@app.route("/admin/inbox/<customer_number>", methods=["GET"])
@admin_required
def admin_inbox_chat(customer_number):
    if not re.fullmatch(r"\d{7,20}", str(customer_number or "")):
        abort(404)
    customer_name = get_inbox_customer_name(customer_number)
    messages = get_inbox_conversation(customer_number, limit=150)
    ai_paused = is_ai_paused(customer_number)
    service_window_open, last_customer_message = is_whatsapp_service_window_open(customer_number)
    last_customer_message_label = (
        last_customer_message.astimezone(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M")
        if last_customer_message else ""
    )
    notice = request.args.get("notice", "")[:40]
    return render_template_string(
        INBOX_CHAT_TEMPLATE,
        customer_number=customer_number,
        customer_name=customer_name,
        messages=messages,
        ai_paused=ai_paused,
        service_window_open=service_window_open,
        last_customer_message_label=last_customer_message_label,
        notice=notice,
        csrf_token=get_csrf_token(),
    )


@app.route("/admin/inbox/<customer_number>/send", methods=["POST"])
@admin_required
def admin_inbox_send(customer_number):
    validate_csrf()
    if not re.fullmatch(r"\d{7,20}", str(customer_number or "")):
        abort(404)
    message = str(request.form.get("message") or "").strip()
    if not message or len(message) > 3500:
        abort(400)

    service_window_open, _last_customer_message = is_whatsapp_service_window_open(customer_number)
    if not service_window_open:
        return redirect(url_for("admin_inbox_chat", customer_number=customer_number, notice="window_closed"))

    # A human reply must never race with the AI. Pause first, then send.
    set_ai_paused(customer_number, True)
    sent = send_whatsapp_message(customer_number, message)
    if sent:
        save_message(customer_number, "assistant", message, sender_label="Jones / IBROWS")
        print(f"IBROWS HUMAN INBOX MESSAGE SENT: customer={customer_number}", flush=True)
        return redirect(url_for("admin_inbox_chat", customer_number=customer_number, notice="sent"))

    print(f"IBROWS HUMAN INBOX MESSAGE FAILED: customer={customer_number}", flush=True)
    return redirect(url_for("admin_inbox_chat", customer_number=customer_number, notice="failed"))


